public void printALinkedList(ListNode head) {
    ListNode c = head;
    while (c != null) {
        System.out.print(c.val + " ");
        c = c.next;
    }
    System.out.println();
}

public ListNode reverseALinkedListInPlaceInOneIteration(ListNode head) {
    ListNode prev = null, curr = head;
    while (curr != null) {
        ListNode next = curr.next;
        curr.next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

public ListNode reverseRecursive(ListNode head) {
    if (head == null || head.next == null) return head;
    ListNode newHead = reverseRecursive(head.next);
    head.next.next = head;
    head.next = null;
    return newHead;
}

public RandomListNode copyRandomList(RandomListNode head) {
    HashMap<RandomListNode, RandomListNode> map = new HashMap<>();
    for (RandomListNode c = head; c != null; c = c.next)
        map.put(c, new RandomListNode(c.label));
    for (RandomListNode c = head; c != null; c = c.next) {
        map.get(c).next   = map.get(c.next);
        map.get(c).random = map.get(c.random);
    }
    return map.get(head);
}

