    for (RandomListNode c = head; c != null; c = c.next.next) {
        RandomListNode clone = new RandomListNode(c.label);
        clone.next = c.next;
        c.next = clone;
    }
    for (RandomListNode c = head; c != null; c = c.next.next)
        if (c.random != null) c.next.random = c.random.next;
